self.HCKaiData = {"items":{"breath-box":{"title":"Box breathing","kind":"breathing"},"breath-478":{"title":"4-7-8 breathing","kind":"breathing"},"breath-46":{"title":"Slow out-breath","kind":"breathing"},"guide-urge":{"title":"Urge surfing","kind":"reading"},"guide-halt":{"title":"HALT","kind":"reading"},"guide-24h":{"title":"24-hour plan","kind":"reading"},"guide-54321":{"title":"5-4-3-2-1 grounding","kind":"reading"},"guide-one":{"title":"One-thing focus","kind":"reading"},"guide-stress":{"title":"Stress and anxiety","kind":"reading"},"body-alcohol":{"title":"Alcohol and the body","kind":"reading"},"body-stimulants":{"title":"Stimulants and the body","kind":"reading"},"body-opioids":{"title":"Opioids and the body","kind":"reading"},"body-cannabis":{"title":"Cannabis and the body","kind":"reading"},"med-urge":{"title":"Urge surfing","kind":"meditation"},"med-scan":{"title":"Body scan","kind":"meditation"},"med-breath":{"title":"Breathing anchor","kind":"meditation"},"med-walk":{"title":"Mindful walking","kind":"meditation"},"med-eat":{"title":"Mindful eating","kind":"meditation"},"fell-aa":{"title":"Alcoholics Anonymous","kind":"fellowship"},"fell-na":{"title":"Narcotics Anonymous","kind":"fellowship"},"fell-ga":{"title":"Gambling support","kind":"fellowship"},"fell-pa":{"title":"Pornography addiction support","kind":"fellowship"}},"steps":{"1":{"theme":"Honesty","note":"Getting honest that drinking or using has been calling the shots, and that willpower on its own hasn't fixed it. It's a starting point, not a judgement of your worth."},"2":{"theme":"Hope","note":"Opening up to the idea that things can get better, with help from beyond yourself. That help can mean faith, the group, or simply people who've been there."},"3":{"theme":"Letting help in","note":"Choosing to stop carrying everything alone. People describe this in their own way: a faith, the fellowship, or the values they want to live by."},"4":{"theme":"Taking stock","note":"Writing an honest list of the patterns, fears and resentments that keep tripping you up, and your strengths as well. Many people do this with a sponsor so it stays fair and kind."},"5":{"theme":"Telling someone","note":"Sharing what you found with one person you trust. Saying it out loud often takes away some of its weight."},"6":{"theme":"Willingness","note":"Becoming ready to let go of habits and reactions that hurt you or others. Willing is enough. Nobody expects perfect."},"7":{"theme":"Humility","note":"Asking, in whatever way fits your beliefs, for help to change those patterns. It's a daily practice more than a one-off moment."},"8":{"theme":"Facing the past","note":"Writing down the people your drinking or using affected, and getting ready to put things right where you can."},"9":{"theme":"Making things right","note":"Repairing harm directly where it's safe and won't cause new hurt. A sponsor or counsellor can help you think through when and how."},"10":{"theme":"Daily check-in","note":"A regular look back at the day: what went well, where old patterns crept in, and owning mistakes early instead of letting them pile up."},"11":{"theme":"Quiet time","note":"Making room for reflection, prayer or meditation, whatever suits you, to stay grounded and clear about what matters."},"12":{"theme":"Passing it on","note":"Living these ideas day to day and offering a hand to people who are where you once were."}},"stages":[{"days":[1,3],"kaiLine":"the first days are often the roughest on the body: shaky, sweaty, unsettled sleep and a busy mind are common.","statID":"adf-alcohol-withdrawal-days"},{"days":[4,7],"kaiLine":"by the end of the first week many people find the sharpest physical stuff easing, while sleep and mood still wobble.","statID":null},{"days":[8,30],"kaiLine":"in weeks two to four many people get a bit more energy back, while sleep settles slowly and cravings come in waves.","statID":"adf-withdrawal-weeks"},{"days":[31,90],"kaiLine":"in months one to three thinking often feels clearer, though mood can still dip and cravings can surprise you.","statID":"adf-benzo-weeks"},{"days":[91,182],"kaiLine":"around three to six months new routines often feel more natural, and rough patches are still common and okay.","statID":"brain-cortex-2023"},{"days":[183,100000],"kaiLine":"from six to twelve months life often feels more like your own, and anniversaries or big changes can still stir things up.","statID":null}],"stats":{"adf-alcohol-withdrawal-days":{"text":"Alcohol withdrawal symptoms can start within a few hours of the last drink and can last for two to seven days.","sourceTitle":"Alcohol (Alcohol and Drug Foundation)","sourceURL":"https://adf.org.au/drug-facts/alcohol/"},"adf-withdrawal-delirium":{"text":"Severe withdrawal delirium happens in about 3 to 5% of people going through alcohol withdrawal. It is a medical emergency.","sourceTitle":"Safely withdrawing from alcohol (Alcohol and Drug Foundation)","sourceURL":"https://adf.org.au/insights/safely-withdrawing-alcohol/"},"adf-withdrawal-weeks":{"text":"Withdrawal generally lasts from a few days to a few weeks, but some things, like cravings, can carry on much longer.","sourceTitle":"Withdrawal (Alcohol and Drug Foundation)","sourceURL":"https://adf.org.au/reducing-risk/withdrawal/"},"adf-benzo-weeks":{"text":"For people coming off benzodiazepines, symptoms mostly ease within a few weeks, though some can last for months.","sourceTitle":"Benzodiazepines (Alcohol and Drug Foundation)","sourceURL":"https://adf.org.au/drug-facts/benzodiazepines/"},"brain-cortex-2023":{"text":"In a small 2023 study of 40 adults treated for alcohol use disorder, the brain's outer layer got thicker again in 25 of 34 regions over about 7 months without alcohol.","sourceTitle":"Durazzo, Stephens and Meyerhoff, 2023 study, Alcohol journal (PMC)","sourceURL":"https://pmc.ncbi.nlm.nih.gov/articles/PMC10902196/"},"abs-anxiety":{"text":"17.2% of Australians aged 16 to 85 had an anxiety disorder in the past 12 months.","sourceTitle":"National Study of Mental Health and Wellbeing 2020–2022 (Australian Bureau of Statistics)","sourceURL":"https://www.abs.gov.au/statistics/health/mental-health/national-study-mental-health-and-wellbeing/latest-release"}},"safetyLine":"Stopping heavy drinking, benzodiazepines or some other drugs suddenly can be dangerous, so talk to a GP first, or call 000 in an emergency.","privateDetails":"Don't share your full name, address, phone, bank details or passwords with anyone in HomeCircle or at meetings. Real friends and sponsors won't ask for money or private details. If someone does, tell your sponsor or a trusted person.","pages":{"breath-box":"library/box-breathing.html","breath-478":"library/4-7-8-breathing.html","breath-46":"library/slow-out-breath.html","guide-urge":"library/urge-surfing.html","guide-halt":"library/halt.html","guide-24h":"library/24-hour-plan.html","guide-54321":"library/grounding-5-4-3-2-1.html","guide-one":"library/one-thing-focus.html","guide-stress":"library/stress-and-anxiety.html","body-alcohol":"library/alcohol-and-the-body.html","body-stimulants":"library/stimulants-and-the-body.html","body-opioids":"library/opioids-and-the-body.html","body-cannabis":"library/cannabis-and-the-body.html","med-urge":"library/urge-surfing-meditation.html","med-scan":"library/body-scan.html","med-breath":"library/breathing-anchor.html","med-walk":"library/mindful-walking.html","med-eat":"library/mindful-eating.html","fell-aa":"library/alcoholics-anonymous.html","fell-na":"library/narcotics-anonymous.html","fell-ga":"library/gambling-support.html","fell-pa":"library/pornography-addiction-support.html","page-twelve-steps":"twelve-steps.html","page-body-stages":"library/body-and-recovery-stages.html","page-recovery-books":"library/recovery-books.html"}};
